#include "market_data/ctp/state_machine.hpp"
#include <gtest/gtest.h>
using namespace market_data::ctp;
TEST(CtpStateMachine,LoginSubscribeReady){StateMachine state{false};EXPECT_EQ(state.start(),Action::none);EXPECT_EQ(state.state(),State::connecting);EXPECT_EQ(state.front_connected(),Action::login);EXPECT_EQ(state.state(),State::logging_in);EXPECT_EQ(state.login_result(true),Action::subscribe);state.subscription_result(true,false);state.subscription_result(true,true);EXPECT_EQ(state.state(),State::ready);}
TEST(CtpStateMachine,AuthenticationPath){StateMachine state{true};state.start();EXPECT_EQ(state.front_connected(),Action::authenticate);EXPECT_EQ(state.state(),State::authenticating);EXPECT_EQ(state.authentication_result(true),Action::login);EXPECT_EQ(state.login_result(true),Action::subscribe);}
TEST(CtpStateMachine,FailuresRemainVisible){StateMachine login{false};login.start();login.front_connected();login.login_result(false);EXPECT_EQ(login.state(),State::error);StateMachine subscription{false};subscription.start();subscription.front_connected();subscription.login_result(true);subscription.subscription_result(false,false);subscription.subscription_result(true,true);EXPECT_EQ(subscription.state(),State::error);}
TEST(CtpStateMachine,DisconnectReconnectRequiresFullSessionAgain){StateMachine state{false};state.start();state.front_connected();state.login_result(true);state.subscription_result(true,true);state.front_disconnected();EXPECT_EQ(state.state(),State::reconnecting);EXPECT_EQ(state.front_connected(),Action::login);EXPECT_TRUE(state.is_reconnect());EXPECT_EQ(state.login_result(true),Action::subscribe);}
